        assert_eq!(to_lower("ẞ"), "ß");
    }

    #[test]
    fn lower_keeps_characters_newer_than_unicode_15() {
        assert_eq!(to_lower("\u{A7CB}"), "\u{A7CB}");
        assert_eq!(to_lower("\u{10D50}A"), "\u{10D50}a");
