                ("a".to_string(), 2),
                ("b".to_string(), 2),
                ("c".to_string(), 2),
                ("d".to_string(), 1)
            ]
        );
        assert_eq!(report.total_words, 7);
        assert_eq!(report.unique_words, 4);
    }

    #[test]
    fn top_limits_entries() {
        let report = count_words(&words(&["x", "y", "x"]), 1);
        assert_eq!(report.top, vec![("x".to_string(), 2)]);
        assert_eq!(report.unique_words, 2);
    }

    #[test]
    fn text_format() {
        let report = count_words(&words(&["rust", "is", "rust"]), 10);
        assert_eq!(format_text(&report), "words: 3\nunique: 2\n2\trust\n1\tis\n");
    }

    #[test]
    fn json_format_keeps_non_ascii_and_escapes_like_python() {
        let report = count_words(&words(&["러스트", "a\"b\\c", "x\u{1}\u{8}\u{7F}"]), 10);
        assert_eq!(
            format_json(&report),
            "{\"words\":3,\"unique\":3,\"top\":[{\"word\":\"a\\\"b\\\\c\",\"count\":1},\
             {\"word\":\"x\\u0001\\b\u{7F}\",\"count\":1},{\"word\":\"러스트\",\"count\":1}]}\n"
        );
    }

    #[test]
    fn empty_json() {
        let report = count_words(&[], 10);
        assert_eq!(format_json(&report), "{\"words\":0,\"unique\":0,\"top\":[]}\n");
    }

    #[test]
    fn parse_defaults_and_options() {
        assert_eq!(
            parse(&["a.txt"]),
            Ok(Command::Run(Options {
                file: "a.txt".into(),
                top: 10,
                json: false
            }))
        );
        assert_eq!(
            parse(&["--json", "--top", "3", "a.txt", "--top=05"]),
            Ok(Command::Run(Options {
                file: "a.txt".into(),
                top: 5,
                json: true
            }))
        );
        assert_eq!(
            parse(&["--", "-a.txt"]),
            Ok(Command::Run(Options {
                file: "-a.txt".into(),
                top: 10,
                json: false
            }))
        );
        assert_eq!(
            parse(&["a.txt", "--top", "99999999999999999999999"]),
            Ok(Command::Run(Options {
                file: "a.txt".into(),
                top: usize::MAX,
                json: false
            }))
        );
        assert_eq!(parse(&["--help"]), Ok(Command::Help));
    }

    #[test]
    fn parse_errors() {
        for args in [
            &[][..],
            &["a.txt", "--top", "0"],
            &["a.txt", "--top", "abc"],
            &["a.txt", "--top", "-1"],
            &["a.txt", "--top", "+5"],
            &["a.txt", "--top", "１"],
            &["a.txt", "--top", "1_0"],
            &["a.txt", "--top"],
            &["a.txt", "--bogus"],
            &["a.txt", "--to", "3"],
            &["a.txt", "b.txt"],
        ] {
            assert!(parse(args).is_err(), "{args:?}");
        }
    }
}

